<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><title>TMS | Manage Sessions</title><script src="https://cdn.tailwindcss.com"></script></head><body class="bg-gray-50 font-sans antialiased text-gray-900 min-h-screen"><main class="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8 space-y-6">@if (session('success'))<div class="rounded-xl bg-emerald-50 text-emerald-700 border border-emerald-200 px-4 py-3 text-sm">{{ session('success') }}</div>@endif<section class="bg-white border border-gray-100 rounded-2xl p-6 shadow-sm flex items-center justify-between"><div><h1 class="text-3xl font-extrabold text-darkSlate">Manage Sessions</h1><p class="text-slateGray mt-1">Create and maintain event sessions.</p></div><a href="{{ route('admin.sessions.create') }}" class="bg-softOrange text-white px-4 py-2 rounded-lg text-sm font-semibold">New Session</a></section><section class="bg-white rounded-2xl border border-gray-100 shadow-sm overflow-hidden"><div class="overflow-x-auto"><table class="min-w-full text-sm"><thead class="bg-gray-50 text-left text-xs uppercase tracking-wider text-slateGray"><tr><th class="px-4 py-3">Session</th><th class="px-4 py-3">Event</th><th class="px-4 py-3">Location</th><th class="px-4 py-3">Start</th><th class="px-4 py-3">Actions</th></tr></thead><tbody class="divide-y divide-gray-100">@forelse($sessions as $session)<tr><td class="px-4 py-4 font-semibold text-darkSlate">{{ $session->session_title ?? 'Untitled Session' }}</td><td class="px-4 py-4">{{ $session->event?->title ?? 'N/A' }}</td><td class="px-4 py-4">{{ $session->location }}</td><td class="px-4 py-4">{{ $session->start_date }}</td><td class="px-4 py-4 space-x-3"><a class="font-semibold text-softMutedTeal" href="{{ route('admin.sessions.edit', $session) }}">Edit</a><form action="{{ route('admin.sessions.destroy', $session) }}" method="POST" class="inline">@csrf @method('DELETE')<button class="font-semibold text-crimson" oncl